def get_icon(name: str, size: int = 18, color: str = "currentColor", extra_class: str = "") -> str:
    """Return inline SVG string for the requested Lucide icon."""
    template = _ICON_SVGS.get(name)
    if not template:
        # Fallback to info icon if name not matched
        template = _ICON_SVGS["info"]
    return template.format(size=size, color=color, extra_class=extra_class)
